function schedulePeriods(cfg,day){return cfg.scheduleMode==='custom'?(cfg.weeklySchedule?.[day]||[]):cfg.days.includes(day)?[{start:cfg.start,end:cfg.end}]:[]}
function weeklyRows(){return ['Domingo','Segunda-feira','Terça-feira','Quarta-feira','Quinta-feira','Sexta-feira','Sábado'].map((name,day)=>{const enabled=weekEnabled[day],periods=weeklyDraft[day];return `<div class="weekly-row ${enabled?'enabled':'disabled'}"><label class="weekday-switch"><input type="checkbox" data-weekday-toggle="${day}" ${enabled?'checked':''} aria-label="Atender ${name}"><span></span><b>${name}</b></label><div class="weekly-periods">${periods.map((p,i)=>`<div class="weekly-period"><span>${i?'e das':'Das'}</span><input type="time" data-weekday="${day}" data-period="${i}" data-period-field="start" value="${esc(p.start)}" ${!enabled?'disabled':''} aria-label="Início ${name} período ${i+1}"><span>às</span><input type="time" data-weekday="${day}" data-period="${i}" data-period-field="end" value="${esc(p.end)}" ${!enabled?'disabled':''} aria-label="Fim ${name} período ${i+1}">${i?`<button type="button" class="remove-period" data-remove-period="${day}:${i}" ${!enabled?'disabled':''} aria-label="Remover período ${i+1} de ${name}">×</button>`:''}</div>`).join('')}<button type="button" class="add-period" data-add-period="${day}" ${!enabled||periods.length>=4?'disabled':''} aria-label="Adicionar período de ${name}">＋</button></div></div>`}).join('')}
